import {validateBackup} from './core.js';
export const DEVICE_KEYS=['gun-payi-quick','gun-payi-draft','gun-payi-voice'];
export function readDevice(storage){return Object.fromEntries(DEVICE_KEYS.map(k=>[k,storage.getItem(k)]));}
export function writeDevice(storage,values){const previous=readDevice(storage);try{for(const k of DEVICE_KEYS){const value=values[k];if(value==null)storage.removeItem(k);else storage.setItem(k,value);}}catch(error){for(const k of DEVICE_KEYS)try{if(previous[k]==null)storage.removeItem(k);else storage.setItem(k,previous[k]);}catch{}throw error;}return previous;}
export function backupText(state,storage){const text=JSON.stringify({...state,exportedAt:new Date().toISOString(),device:{storage:readDevice(storage)}},null,2);parseBackup(text);return text;}
export function parseBackup(text){if(typeof text!=='string'||text.length>20*1024*1024)throw Error('Yedek en fazla 20 MB olabilir.');let raw;try{raw=JSON.parse(text);}catch{throw Error('Panoda geçerli bir JSON yedeği bulunamadı.');}const state=validateBackup(raw),device=raw.device?.storage;if(raw.device!==undefined&&(!device||typeof device!=='object'||Array.isArray(device)))throw Error('Yedekteki taslaklar okunamadı.');const storage={};for(const k of DEVICE_KEYS){const v=device?.[k]??null;if(v!==null){if(typeof v!=='string'||v.length>1000000)throw Error('Yedekteki taslak geçersiz.');let d;try{d=JSON.parse(v);}catch{throw Error('Yedekteki taslak okunamadı.');}if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Yedekteki taslak geçersiz.');if(k==='gun-payi-quick'&&(typeof d.text!=='string'||d.text.length>20000||!['task','note'].includes(d.kind)||d.time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(d.time)))throw Error('Hızlı ekleme taslağı geçersiz.');if(k==='gun-payi-voice'&&(typeof d.text!=='string'||d.text.length>100000))throw Error('Ses metni taslağı geçersiz.');if(k==='gun-payi-draft'&&(!['item','note','goal','review','onboarding','reflection'].includes(d.kind)||!Array.isArray(d.fields)||d.fields.length>100||d.fields.some(x=>!Array.isArray(x)||x.length!==2||x.some(v=>typeof v!=='string'))||!d.meta||typeof d.meta!=='object'))throw Error('Form taslağı geçersiz.');if(k==='gun-payi-draft'){if(Array.isArray(d.meta)||d.fields.some(([name,value])=>name.length>100||value.length>20000))throw Error('Form taslağı geçersiz.');for(const key of ['id','noteId'])if(d.meta[key]!=null&&(typeof d.meta[key]!=='string'||!/^[-_a-zA-Z0-9]{1,150}$/.test(d.meta[key])))throw Error('Taslak kimliği geçersiz.');if(d.meta.area!=null&&!['english','curiosity','movement','faith','social','self','work','personal'].includes(d.meta.area))throw Error('Taslak alanı geçersiz.');if(d.kind==='goal'&&!d.meta.area)throw Error('Hedef taslağı alanı eksik.');}}storage[k]=v;}const clean=Object.fromEntries(['schema','revision','prefs','items','notes','goals','days','reviews'].filter(k=>k in state).map(k=>[k,state[k]]));return {state:clean,storage};}
